10	 * timestamp; a delivery whose timestamp is further than this from now (past or
11	 * future) is rejected, so a captured request cannot be replayed indefinitely.
12	 * Matches the documented 5-minute tolerance.
13	 */
14	const REPLAY_TOLERANCE_SECONDS = 300;
15	const MILLIS_PER_SECOND = 1000;
16	
17	const HEX_PATTERN = /^[0-9a-f]+$/i;
18	const HEX_CHARS_PER_BYTE = 2;
19	const HEX_RADIX = 16;
20	
21	export type VerifyResult =
22	  | { ok: true }
23	  | { ok: false; reason: "missing-headers" | "expired" | "signature-mismatch" };
24	
25	export interface VerifyInput {
26	  /** Request headers, keys lowercased. */
27	  headers: Record<string, string>;
28	  /** Epoch milliseconds; injectable for deterministic tests. */
29	  now?: number;
30	  /** The exact bytes received on the wire — never a re-encoded body. */
31	  rawBody: Uint8Array;
32	  /** The per-webhook signing secret. */
33	  secret: string;
34	}
35	
36	/** Strict hex decode; `null` (not a truncated buffer) on malformed input. */
37	const hexToBytes = (hex: string): Uint8Array<ArrayBuffer> | null => {
38	  if (
39	    hex.length === 0 ||
40	    hex.length % HEX_CHARS_PER_BYTE !== 0 ||
41	    !HEX_PATTERN.test(hex)
42	  ) {
43	    return null;
44	  }
45	  const bytes = new Uint8Array(hex.length / HEX_CHARS_PER_BYTE);
46	  for (let index = 0; index < bytes.length; index += 1) {
47	    const offset = index * HEX_CHARS_PER_BYTE;
48	    bytes[index] = Number.parseInt(
49	      hex.slice(offset, offset + HEX_CHARS_PER_BYTE),
50	      HEX_RADIX
51	    );
52	  }
53	  return bytes;
54	};
55	
56	/**
57	 * Verify a native Spectrum webhook signature.
58	 *
59	 * The header is `X-Spectrum-Signature: v0=<lowercase-hex>` where the hex digest
60	 * is `HMAC-SHA256(secret, "v0:" + timestamp + ":" + rawBody)` and `timestamp`
61	 * is the `X-Spectrum-Timestamp` header (unix seconds). The base string is built
62	 * over the **exact body bytes**: never JSON-parse-then-restringify before
63	 * verifying, or the bytes (key order, whitespace) change and the MAC won't
64	 * match.
65	 *
66	 * Implemented on Web Crypto (hence async) so it runs identically on Node, Bun,
67	 * and V8-isolate runtimes (Convex, Cloudflare Workers, Deno Deploy) — this is
68	 * part of the portable `@spectrum-ts/core/webhook` entry. `subtle` comes from
69	 * `uncrypto`, whose conditional exports pick `node:crypto`'s webcrypto under
70	 * Node and `globalThis.crypto` everywhere else, so this works on Node 18 (where
71	 * the global is not exposed by default) without a runtime feature check.
72	 *
73	 * The digest comparison is `subtle.verify`, which compares MACs in constant
74	 * time.
75	 */
76	export async function verifySpectrumSignature(
77	  input: VerifyInput
78	): Promise<VerifyResult> {
79	  const { rawBody, headers, secret, now = Date.now() } = input;
80	  if (!secret) {
81	    // A missing secret is caller misconfiguration, not an unauthenticated
82	    // request — surface it loudly instead of returning an undebuggable 401.
83	    throw new Error("verifySpectrumSignature: secret must be non-empty");
84	  }
85	  const provided = headers[SIGNATURE_HEADER];
86	  const timestamp = headers[TIMESTAMP_HEADER];
87	  if (!(provided && timestamp)) {
88	    return { ok: false, reason: "missing-headers" };
89	  }
90	
91	  const timestampSeconds = Number(timestamp);
92	  if (!Number.isFinite(timestampSeconds)) {
93	    return { ok: false, reason: "missing-headers" };
94	  }
95	  const nowSeconds = Math.floor(now / MILLIS_PER_SECOND);
96	  if (Math.abs(nowSeconds - timestampSeconds) > REPLAY_TOLERANCE_SECONDS) {
97	    return { ok: false, reason: "expired" };
98	  }
99	
100	  const providedHex = provided.startsWith(SIGNATURE_PREFIX)
101	    ? provided.slice(SIGNATURE_PREFIX.length)
102	    : provided;
103	  const providedBytes = hexToBytes(providedHex);
104	  if (!providedBytes) {
105	    return { ok: false, reason: "signature-mismatch" };
106	  }
107	
108	  const encoder = new TextEncoder();
109	  const prefix = encoder.encode(`${SIGNATURE_SCHEME}:${timestamp}:`);
110	  const base = new Uint8Array(prefix.length + rawBody.length);
111	  base.set(prefix, 0);
112	  base.set(rawBody, prefix.length);
113	
114	  const key = await subtle.importKey(
115	    "raw",
116	    encoder.encode(secret),
117	    { name: "HMAC", hash: "SHA-256" },
118	    false,
119	    ["verify"]
120	  );
121	  const matches = await subtle.verify("HMAC", key, providedBytes, base);
122	  if (!matches) {
123	    return { ok: false, reason: "signature-mismatch" };
124	  }
125	  return { ok: true };
126	}
