31	/**
32	 * Lazy byte accessors for an attachment whose bytes are fetched on demand —
33	 * the native webhook delivers attachment metadata only.
34	 */
35	export interface AttachmentBytes {
36	  read: () => Promise<Buffer>;
37	  stream?: () => Promise<ReadableStream<Uint8Array>>;
38	}
39	
40	export interface DeserializeContext {
41	  /**
42	   * Reconstruct lazy byte accessors for a slim attachment by delegating to the
43	   * owning platform (e.g. iMessage's `getAttachment`). Returns `undefined` when
44	   * the platform exposes no such capability, in which case the attachment is
45	   * delivered metadata-only with a `read()`/`stream()` that throws on use.
46	   */
47	  resolveAttachment?: (
48	    platform: string,
49	    spaceRef: { id: string } & Record<string, unknown>,
50	    attachmentId: string
51	  ) => AttachmentBytes | undefined;
52	}
