59	type SpaceRef = { id: string } & Record<string, unknown>;
60	
61	const isRecord = (value: unknown): value is Record<string, unknown> =>
62	  typeof value === "object" && value !== null;
63	
64	const asString = (value: unknown): string =>
65	  typeof value === "string" ? value : "";
66	
67	const asOptionalDate = (value: unknown): Date | undefined =>
68	  typeof value === "string" ? new Date(value) : undefined;
