70	/**
71	 * Map a native Spectrum webhook envelope to a `ProviderMessageRecord` plus the
72	 * platform that owns it, ready for `resolveRecordToMessages`. Returns `null`
73	 * when the delivery carries nothing to route (an unknown `event` type, or a
74	 * message with no resolvable platform) — the caller acknowledges it (200)
75	 * rather than failing, since neither is fixed by a retry.
76	 *
77	 * Reaction/reply targets and group items are emitted as **raw nested records**;
78	 * the `wrapProviderMessage`/`wrapNestedContent` pipeline turns them into
79	 * fully-built Messages, exactly as a provider's own `messages` handler would.
80	 */
81	export function deserializeSpectrumMessage(
82	  envelope: SlimEnvelope,
83	  ctx: DeserializeContext
84	): DeserializeResult | null {
85	  if (envelope.event !== MESSAGES_EVENT) {
86	    return null;
87	  }
88	  const message = envelope.message;
89	  const platform = resolvePlatform(message);
90	  if (!platform) {
91	    return null;
92	  }
93	  const spaceRef: SpaceRef = { ...message.space };
94	  return {
95	    platform,
96	    record: {
97	      id: message.id,
98	      direction: "inbound",
99	      content: deserializeContent(message.content, platform, spaceRef, ctx),
100	      space: spaceRef,
101	      sender: message.sender ? { ...message.sender } : undefined,
102	      timestamp: asOptionalDate(message.timestamp),
103	    },
104	  };
105	}
106	
107	const resolvePlatform = (message: SlimMessage): string | undefined =>
108	  message.platform ?? message.space.platform;
109	
110	// A wire content arm we couldn't map cleanly still reaches the handler as
111	// `custom` (carrying the original JSON) rather than failing the whole delivery.
112	const deserializeContent = (
113	  content: SlimContent,
114	  platform: string,
115	  spaceRef: SpaceRef,
116	  ctx: DeserializeContext
117	): Content => {
118	  try {
119	    return mapContent(content, platform, spaceRef, ctx);
120	  } catch {
121	    return asCustom(content);
122	  }
123	};
