125	const mapContent = (
126	  content: SlimContent,
127	  platform: string,
128	  spaceRef: SpaceRef,
129	  ctx: DeserializeContext
130	): Content => {
131	  const raw = content as Record<string, unknown>;
132	  switch (content.type) {
133	    case "text":
134	      return { type: "text", text: asString(raw.text) };
135	    case "richlink":
136	      // Outbound-only content type; inbound URLs always surface as text.
137	      return { type: "text", text: asString(raw.url) };
138	    case "contact":
139	      return deserializeContact(raw);
140	    case "reaction":
141	      return deserializeReaction(raw, spaceRef);
142	    case "read":
143	      return deserializeRead(raw, spaceRef);
144	    case "reply":
145	      return deserializeReply(raw, platform, spaceRef, ctx);
146	    case "group":
147	      return deserializeGroup(raw, platform, spaceRef, ctx);
148	    case "attachment":
149	      return deserializeAttachment(raw, platform, spaceRef, ctx);
150	    case "voice":
151	      return deserializeVoice(raw, platform, spaceRef, ctx);
152	    case "addMember":
153	      return addMemberSchema.parse({
154	        type: "addMember",
155	        members: memberStrings(raw.members),
156	      });
157	    case "removeMember":
158	      return removeMemberSchema.parse({
159	        type: "removeMember",
160	        members: memberStrings(raw.members),
161	      });
162	    case "leaveSpace":
163	      // The leaver rides on the envelope (`message.sender`), not the content.
164	      return leaveSpaceSchema.parse({ type: "leaveSpace" });
165	    case "rename":
